import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class ShipmentKeyTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            ShipmentKey a = new ShipmentKey("ups", 70041);
            ShipmentKey b = new ShipmentKey("UPS", 70041);
            ShipmentKey c = new ShipmentKey("ups", 9);
            ShipmentKey d = new ShipmentKey("fedex", 70041);

            check("toString", "UPS#70041", a.toString());
            check("equal ignoring carrier case", true, a.equals(b));
            check("equal keys share a hashCode", true, a.hashCode() == b.hashCode());
            check("different tracking number", false, a.equals(c));
            check("different carrier", false, a.equals(d));
            check("not equal to null", false, a.equals(null));
            check("not equal to a String", false, a.equals("UPS#70041"));
            check("equal to itself", true, a.equals(a));

            Map<ShipmentKey, String> parcels = new HashMap<>();
            parcels.put(a, "books");
            check("lookup with an equal but different key", "books", parcels.get(b));
            parcels.put(b, "shoes");
            check("putting an equal key replaces the value", "shoes", parcels.get(a));
            check("map holds one entry", 1, parcels.size());
            parcels.put(d, "kettle");
            check("map holds two entries", 2, parcels.size());

            Set<ShipmentKey> seen = new HashSet<>();
            seen.add(a);
            seen.add(b);
            seen.add(c);
            check("HashSet folds the duplicate", 2, seen.size());
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

