import java.util.Objects;

public class ShipmentKey {

    private final String carrier;
    private final int trackingNumber;

    public ShipmentKey(String carrier, int trackingNumber) {
        this.carrier = carrier == null ? "" : carrier;
        this.trackingNumber = trackingNumber;
    }

    public String getCarrier() {
        return carrier;
    }

    public int getTrackingNumber() {
        return trackingNumber;
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (!(other instanceof ShipmentKey)) {
            return false;
        }
        ShipmentKey that = (ShipmentKey) other;
        return trackingNumber == that.trackingNumber
                && carrier.equalsIgnoreCase(that.carrier);
    }

    @Override
    public int hashCode() {
        return Objects.hash(carrier.toLowerCase(), trackingNumber);
    }

    @Override
    public String toString() {
        return carrier.toUpperCase() + "#" + trackingNumber;
    }
}
